// frontend/src/components/screening-results/BiomarkerVisualisation.jsx
// Screening-specific biomarker card for approximate cup-to-disc ratio (CDR).
//
// Data source:
// - Uses cdr, disc_radius, and cup_radius from the selected screening result.
// - These values are generated by the backend CDR approximation pipeline.
//
// Important clinical wording:
// - Always label the value as "Approximate CDR".
// - This is not a validated segmentation model.
// - Validation remains "Pending" until compared against expert/manual masks.

function toNumber(value) {
  if (value === null || value === undefined || value === "") {
    return null;
  }

  const parsed = Number(value);
  return Number.isFinite(parsed) ? parsed : null;
}

function formatCdr(value) {
  const number = toNumber(value);
  return number === null ? "N/A" : number.toFixed(3);
}

function formatPx(value) {
  const number = toNumber(value);
  return number === null ? "N/A" : `${Math.round(number)} px`;
}

function getCdrStatus(cdr) {
  const value = toNumber(cdr);

  if (value === null) {
    return {
      key: "pending",
      label: "Segmentation pending",
      shortLabel: "Pending",
      tone: "neutral",
      range: "N/A",
      description: "Approximate CDR is not available for this screening.",
    };
  }

  if (value < 0.5) {
    return {
      key: "normal",
      label: "Normal range",
      shortLabel: "Normal",
      tone: "positive",
      range: "< 0.50",
      description:
        "Approximate CDR is below 0.50. This does not rule out glaucoma on its own.",
    };
  }

  if (value <= 0.7) {
    return {
      key: "borderline",
      label: "Borderline range",
      shortLabel: "Borderline",
      tone: "warning",
      range: "0.50 to 0.70",
      description:
        "Approximate CDR is in the borderline range and should be interpreted with the full screening context.",
    };
  }

  return {
    key: "suspicious",
    label: "Suspicious range",
    shortLabel: "Suspicious",
    tone: "negative",
    range: "> 0.70",
    description:
      "Approximate CDR is above 0.70 and may support referral when consistent with the full screening result.",
  };
}

function toneClasses(tone) {
  if (tone === "positive") {
    return {
      text: "text-pos",
      strongText: "text-pos",
      border: "border-pos/30",
      softBorder: "border-pos/20",
      bg: "bg-pos/10",
      softBg: "bg-pos/5",
    };
  }

  if (tone === "warning") {
    return {
      text: "text-warn",
      strongText: "text-warn",
      border: "border-warn/30",
      softBorder: "border-warn/20",
      bg: "bg-warn/10",
      softBg: "bg-warn/5",
    };
  }

  if (tone === "negative") {
    return {
      text: "text-neg",
      strongText: "text-neg",
      border: "border-neg/30",
      softBorder: "border-neg/20",
      bg: "bg-neg/10",
      softBg: "bg-neg/5",
    };
  }

  return {
    text: "text-text3",
    strongText: "text-text1",
    border: "border-white/10",
    softBorder: "border-white/7",
    bg: "bg-surface2",
    softBg: "bg-surface2",
  };
}

function CheckIcon({ className = "" }) {
  return (
    <svg
      viewBox="0 0 20 20"
      className={className}
      aria-hidden="true"
    >
      <path
        fill="currentColor"
        d="M8.4 13.6 4.9 10.1l1.2-1.2 2.3 2.3 5.5-5.5 1.2 1.2-6.7 6.7Z"
      />
    </svg>
  );
}

function InfoIcon({ className = "" }) {
  return (
    <svg
      viewBox="0 0 20 20"
      className={className}
      aria-hidden="true"
    >
      <path
        fill="currentColor"
        d="M9.1 8.4h1.8v6H9.1v-6Zm0-2.8h1.8v1.8H9.1V5.6ZM10 2a8 8 0 1 0 0 16 8 8 0 0 0 0-16Zm0 14.3A6.3 6.3 0 1 1 10 3.7a6.3 6.3 0 0 1 0 12.6Z"
      />
    </svg>
  );
}

function GearIcon({ className = "" }) {
  return (
    <svg
      viewBox="0 0 20 20"
      className={className}
      aria-hidden="true"
    >
      <path
        fill="currentColor"
        d="M10 6.8A3.2 3.2 0 1 0 10 13.2 3.2 3.2 0 0 0 10 6.8Zm0 4.8A1.6 1.6 0 1 1 10 8.4a1.6 1.6 0 0 1 0 3.2Zm7.2-1.1V9.5l-2-.5a5.8 5.8 0 0 0-.5-1.3l1-1.8-1.6-1.6-1.8 1a5.8 5.8 0 0 0-1.3-.5l-.5-2h-2l-.5 2a5.8 5.8 0 0 0-1.3.5l-1.8-1-1.6 1.6 1 1.8A5.8 5.8 0 0 0 4.8 9l-2 .5v2l2 .5c.1.5.3.9.5 1.3l-1 1.8 1.6 1.6 1.8-1c.4.2.8.4 1.3.5l.5 2h2l.5-2c.5-.1.9-.3 1.3-.5l1.8 1 1.6-1.6-1-1.8c.2-.4.4-.8.5-1.3l2-.5Z"
      />
    </svg>
  );
}

function ShieldIcon({ className = "" }) {
  return (
    <svg
      viewBox="0 0 20 20"
      className={className}
      aria-hidden="true"
    >
      <path
        fill="currentColor"
        d="M10 1.8 3.8 4v4.8c0 4.1 2.6 7.8 6.2 9.4 3.6-1.6 6.2-5.3 6.2-9.4V4L10 1.8Zm0 14.6c-2.7-1.3-4.6-4.2-4.6-7.6V5.2L10 3.6l4.6 1.6v3.6c0 3.4-1.9 6.3-4.6 7.6Z"
      />
    </svg>
  );
}

function RangeRow({ label, range, tone, active }) {
  const tokenMap = {
    positive: {
      color: "var(--pos)",
      soft: "var(--pos-dim)",
    },
    warning: {
      color: "var(--warn)",
      soft: "var(--warn-dim)",
    },
    negative: {
      color: "var(--neg)",
      soft: "var(--neg-dim)",
    },
  };

  const token = tokenMap[tone] || tokenMap.positive;

  return (
    <div
      className="flex items-center justify-between gap-3 rounded-xl border px-4 py-3 transition"
      style={{
        backgroundColor: active ? token.soft : "var(--surface2)",
        borderColor: active ? token.color : "var(--border)",
      }}
    >
      <div className="flex items-center gap-3">
        <span
          className="w-6 h-6 rounded-full flex items-center justify-center"
          style={{
            backgroundColor: token.soft,
            color: token.color,
          }}
        >
          {active ? (
            <CheckIcon className="w-4 h-4" />
          ) : (
            <span
              className="w-2.5 h-2.5 rounded-full"
              style={{ backgroundColor: token.color }}
            />
          )}
        </span>

        <span
          className="text-sm font-semibold"
          style={{
            color: active ? token.color : "var(--text1)",
          }}
        >
          {label}
        </span>
      </div>

      <span className="text-sm font-semibold" style={{ color: "var(--text1)" }}>
        {range}
      </span>
    </div>
  );
}

function InfoRow({ icon, label, value, valueClassName = "text-text1" }) {
  return (
    <div className="bg-surface2 border border-white/7 rounded-xl p-4 flex items-center justify-between gap-4">
      <div className="flex items-center gap-3">
        <span className="w-8 h-8 rounded-full bg-info/10 text-info flex items-center justify-center">
          {icon}
        </span>

        <span className="text-sm font-semibold text-text1">{label}</span>
      </div>

      <span className={`text-sm font-semibold text-right ${valueClassName}`}>
        {value}
      </span>
    </div>
  );
}

function PendingPlaceholder() {
  return (
    <div className="bg-surface border border-white/7 rounded-xl overflow-hidden">
      <div className="px-5 py-4 border-b border-white/7 flex items-center justify-between gap-3">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-sm font-semibold text-text1">
              Biomarker Visualisation
            </span>
            <span className="text-[10px] px-2 py-0.5 rounded-full bg-warn/10 text-warn border border-warn/20">
              Approximate
            </span>
          </div>

          <p className="text-xs text-text3 mt-1">
            Screening-specific optic disc and cup approximation from the uploaded fundus image.
          </p>
        </div>

        <span className="text-[10px] px-2 py-0.5 rounded-full bg-surface2 text-text3 border border-white/7">
          Pending
        </span>
      </div>

      <div className="p-5">
        <div className="bg-surface2 border border-white/7 rounded-xl p-6 text-center">
          <div className="text-sm font-semibold text-text1">
            Approximate CDR unavailable <br />
            The optic disc/cup approximation could not produce a reliable value for this screening.
          </div>

          <p className="text-xs text-text3 mt-2 max-w-xl mx-auto">
            Approximate CDR is not available for this screening. The biomarker
            card requires cdr, disc_radius, and cup_radius from the screening
            result.
          </p>
        </div>
      </div>
    </div>
  );
}

function BiomarkerVisualisation({ result }) {
  const cdr = toNumber(result?.cdr);
  const discRadiusPx = toNumber(result?.disc_radius);
  const cupRadiusPx = toNumber(result?.cup_radius);

  // Treat the card as pending only when all required backend values are missing.
  const hasBiomarkerValues =
    cdr !== null && discRadiusPx !== null && cupRadiusPx !== null;

  if (!hasBiomarkerValues) {
    return <PendingPlaceholder />;
  }

  const status = getCdrStatus(cdr);
  const statusClasses = toneClasses(status.tone);

  // SVG layout constants.
  // Adjust these values if you want the diagram larger, smaller, or more centred.
  const svgSize = 360;
  const center = svgSize / 2;
  const visualDiscRadius = 120;

  // Draw the optic cup based on actual CDR.
  // The visual disc remains fixed so screenshots are consistent across patients.
  const visualCupRadius = Math.max(
    18,
    Math.min(visualDiscRadius * cdr, visualDiscRadius)
  );

  const showThinningNote = cdr > 0.5;
  const validationLabel =
    result?.cdr_validated === true ? "Validated" : "Pending";

  const methodLabel =
    result?.cdr_method === "classical_approximation" || !result?.cdr_method
      ? "Classical approximation"
      : String(result.cdr_method).replaceAll("_", " ");

  return (
    <div className="bg-surface border border-white/7 rounded-xl overflow-hidden">
      <div className="px-5 py-4 border-b border-white/7 flex items-center justify-between gap-3">
        <div>
          <div className="flex items-center gap-2">
            <span className="text-sm font-semibold text-text1">
              Biomarker Visualisation
            </span>

            <span className="text-[10px] px-2 py-0.5 rounded-full bg-warn/10 text-warn border border-warn/20">
              Approximate
            </span>
          </div>

          <p className="text-xs text-text3 mt-1">
            Screening-specific optic disc and cup approximation from the uploaded fundus image.
          </p>
        </div>

        <span
          className={[
            "text-[10px] px-3 py-1 rounded-full border whitespace-nowrap",
            statusClasses.bg,
            statusClasses.text,
            statusClasses.border,
          ].join(" ")}
        >
          {status.label}
        </span>
      </div>

      <div className="p-5 grid grid-cols-1 xl:grid-cols-[0.95fr_1.05fr] gap-5">
        <div className="bg-surface2 border border-white/7 rounded-xl p-5">
          <div>
            <div className="text-sm font-semibold text-text1">
              Optic Disc / Cup Approximation
            </div>
            <p className="text-xs text-text3 mt-1">
              Outer circle = optic disc, inner circle = optic cup
            </p>
          </div>

          <div className="flex justify-center py-5">
            <svg
              width={svgSize}
              height={svgSize}
              viewBox={`0 0 ${svgSize} ${svgSize}`}
              role="img"
              aria-label="Approximate optic disc and cup diagram"
            >
              <defs>
                <radialGradient id="discGradient" cx="50%" cy="50%" r="50%">
                  <stop offset="0%" stopColor="rgba(45, 130, 124, 0.22)" />
                  <stop offset="100%" stopColor="rgba(45, 130, 124, 0.08)" />
                </radialGradient>

                <radialGradient id="cupGradient" cx="50%" cy="50%" r="50%">
                  <stop offset="0%" stopColor="rgba(132, 184, 92, 0.28)" />
                  <stop offset="100%" stopColor="rgba(132, 184, 92, 0.12)" />
                </radialGradient>
              </defs>

              <circle
                cx={center}
                cy={center}
                r={visualDiscRadius}
                fill="url(#discGradient)"
                stroke="rgba(45, 130, 124, 0.95)"
                strokeWidth="2.5"
              />

              <circle
                cx={center}
                cy={center}
                r={visualCupRadius}
                fill="url(#cupGradient)"
                stroke="rgba(132, 184, 92, 0.95)"
                strokeWidth="2"
              />

              <text
                x={center}
                y={center - 4}
                textAnchor="middle"
                className="fill-text1"
                style={{ fontSize: 28, fontWeight: 800 }}
              >
                {formatCdr(cdr)}
              </text>

              <text
                x={center}
                y={center + 24}
                textAnchor="middle"
                className="fill-text3"
                style={{ fontSize: 12, fontWeight: 600 }}
              >
                Approx. CDR
              </text>
            </svg>
          </div>

          <div className="bg-surface border border-white/7 rounded-xl p-4 grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="space-y-3">
              <div className="flex items-center justify-between gap-3">
                <div className="flex items-center gap-2 text-xs text-text1">
                  <span className="w-4 h-4 rounded-full border-2 border-[rgba(45,130,124,0.95)]" />
                  Disc radius
                </div>
                <span className="text-xs font-semibold font-mono text-text1">
                  {formatPx(discRadiusPx)}
                </span>
              </div>

              <div className="flex items-center justify-between gap-3">
                <div className="flex items-center gap-2 text-xs text-text1">
                  <span className="w-4 h-4 rounded-full border-2 border-[rgba(132,184,92,0.95)]" />
                  Cup radius
                </div>
                <span className="text-xs font-semibold font-mono text-text1">
                  {formatPx(cupRadiusPx)}
                </span>
              </div>
            </div>

            <div className="space-y-3 md:border-l md:border-white/7 md:pl-4">
              <div className="flex items-center gap-2 text-xs text-text1">
                <span className="w-4 h-4 rounded-full bg-[rgba(45,130,124,0.35)]" />
                Disc (optic disc)
              </div>

              <div className="flex items-center gap-2 text-xs text-text1">
                <span className="w-4 h-4 rounded-full bg-[rgba(132,184,92,0.35)]" />
                Cup (optic cup)
              </div>
            </div>
          </div>

          <div
            className={[
              "mt-4 rounded-xl border px-4 py-3 flex items-center justify-center gap-2",
              statusClasses.softBg,
              statusClasses.softBorder,
            ].join(" ")}
          >
            <span
              className={[
                "w-7 h-7 rounded-full flex items-center justify-center",
                statusClasses.bg,
                statusClasses.text,
              ].join(" ")}
            >
              <CheckIcon className="w-5 h-5" />
            </span>

            <span className={`text-sm font-semibold ${statusClasses.text}`}>
              Approximate CDR = {formatCdr(cdr)} · {status.shortLabel}
            </span>
          </div>

          <div className="mt-3 bg-surface border border-white/7 rounded-xl px-4 py-3 flex items-center gap-3">
            <span className="w-7 h-7 rounded-full bg-info/10 text-info flex items-center justify-center">
              <InfoIcon className="w-4 h-4" />
            </span>

            <p className="text-xs text-text3 leading-relaxed">
              {showThinningNote
                ? "Thinning indicators may be relevant because approximate CDR is above 0.50."
                : "Thinning indicators not triggered: approximate CDR is below 0.50."}
            </p>
          </div>
        </div>

        <div className="bg-surface2 border border-white/7 rounded-xl p-5">
          <div>
            <div className="text-sm font-semibold text-text3">
              Approximate CDR
            </div>

            <div className={`text-5xl font-bold font-mono mt-2 ${statusClasses.text}`}>
              {formatCdr(cdr)}
            </div>

            <p className="text-sm text-text3 mt-3 leading-relaxed">
              {status.description}
            </p>
          </div>

          <div className="mt-5 space-y-3">
            <RangeRow
              label="Normal"
              range="< 0.50"
              tone="positive"
              active={status.key === "normal"}
            />

            <RangeRow
              label="Borderline"
              range="0.50 - 0.70"
              tone="warning"
              active={status.key === "borderline"}
            />

            <RangeRow
              label="Suspicious"
              range="> 0.70"
              tone="negative"
              active={status.key === "suspicious"}
            />
          </div>

          <div className="mt-5 grid grid-cols-1 md:grid-cols-2 gap-3">
            <InfoRow
              icon={<GearIcon className="w-4 h-4" />}
              label="Method"
              value={methodLabel}
            />

            <InfoRow
              icon={<ShieldIcon className="w-4 h-4" />}
              label="Validation"
              value={validationLabel}
              valueClassName={
                result?.cdr_validated === true ? "text-pos" : "text-warn"
              }
            />
          </div>

          <div className="mt-5 bg-info/5 border border-info/20 rounded-xl p-4 flex items-start gap-3">
            <span className="w-8 h-8 rounded-full bg-info/10 text-info flex items-center justify-center shrink-0">
              <InfoIcon className="w-4 h-4" />
            </span>

            <p className="text-xs text-text3 leading-relaxed">
              Approximate CDR is calculated using classical image processing and
              Grad-CAM++ guided ROI detection. A dedicated segmentation model is
              planned as future work.
            </p>
          </div>
        </div>
      </div>
    </div>
  );
}

export default BiomarkerVisualisation;
